use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

/// Encode a string as a JSON string literal, escaping as needed.
fn json_string(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                let v = c as u32;
                out.push_str("\\u00");
                let hex = b"0123456789abcdef";
                out.push(hex[((v >> 4) & 0xf) as usize] as char);
                out.push(hex[(v & 0xf) as usize] as char);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Serialize the subscription list as `{"urls":[...]}`.
fn encode_input(subscriptions: &SubscriptionList) -> String {
    let mut out = String::from("{\"urls\":[");
    for (i, url) in subscriptions.urls.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        json_string(url, &mut out);
    }
    out.push_str("]}");
    out
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input received on this call in the shared store.
        state_rw::put("last-input", &encode_input(&subscriptions));

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls.iter() {
            match http_client::fetch(url) {
                Ok(body) => documents.push(FeedDocument {
                    url: url.clone(),
                    body,
                }),
                Err(error) => failures.push(FetchFailure {
                    url: url.clone(),
                    error,
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
